1	import { z } from "zod";
2	import { serviceDb } from "@/lib/bank/server";
3	import { minorDigits } from "@/lib/finance/fx";
4	import type { ScalableMcp } from "./client";
5	import { scalableConfigured } from "./server";
6	
7	// Live, read-only Scalable answers for chat and calls, trimmed to what a question needs. Amounts are exact
8	// minor units with their currency (chat adds the formatted text); Scalable's own figures are never recomputed.
9	
10	export const READ_ONLY_TRADING = "Your Scalable connection only allows read access, so Moneo can't buy or sell for you. To trade from Moneo, turn on full access for AI agents in the Scalable app under Profile → Security.";
11	
12	/** The workspace's active Scalable connection, or null when there is none (or this install cannot hold one). */
13	export async function activeScalableConnection(workspaceId: string): Promise<{ id: string; tradingAccess: "full" | "read" | null } | null> {
14	  if (!scalableConfigured()) return null;
15	  const { data, error } = await serviceDb().from("scalable_connections").select("id, trading_access").eq("workspace_id", workspaceId).eq("status", "active")
16	    .order("created_at", { ascending: false }).limit(1).maybeSingle();
17	  if (error) throw new Error(error.message);
18	  return data ? { id: data.id, tradingAccess: data.trading_access ?? null } : null;
19	}
20	
21	/** Full access lists the order tools; read-only access does not. */
22	export async function tradingAccess(mcp: Pick<ScalableMcp, "listTools">): Promise<"full" | "read"> {
23	  const names = new Set((await mcp.listTools()).map(tool => tool.name));
24	  return ["preview_buy_order", "preview_sell_order", "submit_buy_order", "submit_sell_order"].every(name => names.has(name)) ? "full" : "read";
25	}
