27	const decimal = z.union([z.number().finite(), z.string().regex(/^-?\d+(\.\d+)?$/)]);
28	const code = z.string().regex(/^[A-Z]{3}$/);
29	/** A Scalable decimal (number or string) in exact minor units, rounded half away from zero. */
30	export function toMinor(value: number | string, currency: string): string {
31	  const text = typeof value === "number" ? value.toFixed(12) : value;
32	  const negative = text.startsWith("-"), [whole, fraction = ""] = (negative ? text.slice(1) : text).split(".");
33	  const digits = minorDigits(currency), padded = fraction.padEnd(digits + 1, "0");
34	  let minor = BigInt(whole + padded.slice(0, digits));
35	  if (Number(padded[digits]) >= 5) minor += 1n;
36	  return (negative && minor !== 0n ? -minor : minor).toString();
37	}
38	/** Gain over cost in percent with two decimals, or null without a cost. */
39	const percent = (gain: bigint, cost: bigint) => cost > 0n ? Number(gain * 10000n / cost) / 100 : null;
40	
41	const holdingsSchema = z.object({
42	  holdings: z.array(z.object({ isin: z.string(), name: z.string(), fifoPrice: decimal.nullable().optional(), valuation: decimal, valuationCurrency: code,
43	    currentQuote: z.object({ midPrice: decimal, currency: code, timestamp: z.string().optional() }), position: z.object({ filled: decimal, pending: decimal.optional() }) })).default([]),
44	  cryptoHoldings: z.array(z.object({ ticker: z.string(), name: z.string(), position: z.object({ filled: decimal }).nullable().optional() })).default([]),
45	});
46	const overviewSchema = z.object({
47	  valuation: z.object({ total: decimal, securities: decimal.default(0), crypto: decimal.default(0) }),
48	  timestamps: z.object({ valuationTimestampUtc: z.string() }).partial().optional(),
49	  performance: z.array(z.object({ timeframe: z.string(), simpleAbsoluteReturn: decimal.nullable() })).default([]),
50	});
51	const cashSchema = z.object({ cash: z.object({ cashBalance: decimal, buyingPower: decimal.optional(), pendingBuyOrdersAmount: decimal.optional() }) });
52	
53	/** Labels for Scalable's return periods, shortest first. */
54	export const PERIODS: Record<string, string> = { INTRADAY: "Today", ONE_WEEK: "1 week", ONE_MONTH: "1 month", THREE_MONTHS: "3 months", SIX_MONTHS: "6 months",
55	  YEAR_TO_DATE: "This year", ONE_YEAR: "1 year", MAX: "All time" };
56	
57	/** Holdings, gains, cash and Scalable's returns per period, read live. */
58	export async function investmentsPortfolio(mcp: ScalableMcp, currency = "EUR") {
59	  const [holdings, overview, cash, access] = await Promise.all([mcp.callTool("get_portfolio_holdings").then(value => holdingsSchema.parse(value)),
60	    mcp.callTool("get_portfolio_overview", { includeYearToDate: true }).then(value => overviewSchema.parse(value)),
61	    mcp.callTool("get_portfolio_cash_breakdown").then(value => cashSchema.parse(value)), tradingAccess(mcp)]);
62	  const positions = holdings.holdings.filter(holding => Number(holding.position.filled) > 0).map(holding => {
63	    const shares = Number(holding.position.filled), valueMinor = BigInt(toMinor(holding.valuation, holding.valuationCurrency));
64	    const costMinor = holding.fifoPrice ? BigInt(toMinor(Number(holding.fifoPrice) * shares, holding.valuationCurrency)) : null;
65	    return { isin: holding.isin, name: holding.name, shares: String(holding.position.filled), currencyCode: holding.valuationCurrency,
66	      priceMinor: toMinor(holding.currentQuote.midPrice, holding.currentQuote.currency), valueMinor: valueMinor.toString(),
67	      costMinor: costMinor?.toString() ?? null, gainMinor: costMinor === null ? null : (valueMinor - costMinor).toString(),
68	      gainPercent: costMinor === null ? null : percent(valueMinor - costMinor, costMinor) };
69	  }).sort((a, b) => Number(BigInt(b.valueMinor) - BigInt(a.valueMinor)));
70	  return {
71	    valuedAt: overview.timestamps?.valuationTimestampUtc ?? null, currencyCode: currency, tradingAccess: access,
72	    totalMinor: toMinor(overview.valuation.total, currency), securitiesMinor: toMinor(overview.valuation.securities, currency),
73	    cryptoMinor: toMinor(overview.valuation.crypto, currency), cashMinor: toMinor(cash.cash.cashBalance, currency),
74	    buyingPowerMinor: toMinor(cash.cash.buyingPower ?? cash.cash.cashBalance, currency), pendingBuyOrdersMinor: toMinor(cash.cash.pendingBuyOrdersAmount ?? 0, currency),
75	    returns: Object.keys(PERIODS).flatMap(timeframe => { const entry = overview.performance.find(item => item.timeframe === timeframe);
76	      return entry && entry.simpleAbsoluteReturn !== null ? [{ period: PERIODS[timeframe], returnMinor: toMinor(entry.simpleAbsoluteReturn, currency) }] : []; }),
77	    positions,
78	    crypto: holdings.cryptoHoldings.filter(coin => Number(coin.position?.filled ?? 0) > 0).map(coin => ({ name: coin.name, ticker: coin.ticker, quantity: String(coin.position!.filled) })),
79	  };
80	}
