82	const transactionsSchema = z.object({ transactions: z.array(z.object({
83	  id: z.string(), kind: z.string(), status: z.string(), currency: code.optional(), lastEventAt: z.string(), description: z.string().nullable().optional(),
84	  security: z.object({ isin: z.string(), transactionType: z.string().nullable().optional(), quantity: decimal.nullable().optional(), amount: decimal.nullable().optional(),
85	    side: z.string().nullable().optional(), limitPrice: decimal.nullable().optional() }).nullable().optional(),
86	  cash: z.object({ transactionType: z.string().nullable().optional(), amount: decimal.nullable().optional() }).nullable().optional(),
87	  nonTradeSecurity: z.object({ isin: z.string().nullable().optional(), transactionType: z.string().nullable().optional(), amount: decimal.nullable().optional() }).passthrough().nullable().optional(),
88	})).default([]), page: z.object({ nextCursor: z.string().nullable().optional(), totalCount: z.number().optional() }).optional() });
89	
90	export const transactionsInput = z.object({
91	  from: z.iso.date().optional().describe("First day, inclusive"), to: z.iso.date().optional().describe("Last day, inclusive"),
92	  isin: z.string().regex(/^[A-Z]{2}[A-Z0-9]{9}\d$/).optional(), search: z.string().trim().min(1).max(100).optional(),
93	  types: z.array(z.string().max(40)).max(5).optional().describe("e.g. buy, sell, deposit, withdrawal, dividend"),
94	  statuses: z.array(z.string().max(40)).max(5).optional().describe("e.g. pending for open orders, settled, cancelled"),
95	  limit: z.number().int().min(1).max(50).optional(),
96	}).strict();
97	
98	export type InvestmentTransaction = ReturnType<typeof readTransactions>[number];
99	export function readTransactions(value: unknown) {
100	  return transactionsSchema.parse(value).transactions.map(row => {
101	    const currency = row.currency ?? "EUR", amount = row.security?.amount ?? row.cash?.amount ?? row.nonTradeSecurity?.amount ?? null;
102	    return { id: row.id, date: row.lastEventAt.slice(0, 10), status: row.status, description: row.description ?? null,
103	      type: (row.security?.side ?? row.security?.transactionType ?? row.cash?.transactionType ?? row.nonTradeSecurity?.transactionType ?? row.kind).toString().toLowerCase(),
104	      isin: row.security?.isin ?? row.nonTradeSecurity?.isin ?? null, shares: row.security?.quantity == null ? null : String(row.security.quantity),
105	      limitPriceMinor: row.security?.limitPrice == null ? null : toMinor(row.security.limitPrice, currency),
106	      currencyCode: currency, amountMinor: amount === null ? null : toMinor(amount, currency) };
107	  });
108	}
