110	/** Buys, sells, deposits, withdrawals and dividends, newest first; `id` is what an order cancellation needs. */
111	export async function investmentsTransactions(mcp: ScalableMcp, input: z.infer<typeof transactionsInput>) {
112	  const raw = await mcp.callTool("list_portfolio_transactions", { pageSize: input.limit ?? 20,
113	    ...(input.from ? { fromTime: `${input.from}T00:00:00.000Z` } : {}), ...(input.to ? { toTime: `${input.to}T23:59:59.999Z` } : {}),
114	    ...(input.isin ? { isin: input.isin } : {}), ...(input.search ? { searchTerm: input.search } : {}),
115	    ...(input.types ? { transactionTypes: input.types } : {}), ...(input.statuses ? { statuses: input.statuses } : {}) });
116	  const page = transactionsSchema.parse(raw).page;
117	  return { transactions: readTransactions(raw), more: Boolean(page?.nextCursor) };
118	}
119	
120	export const securityInput = z.object({
121	  action: z.enum(["search", "quote", "chart", "news"]),
122	  query: z.string().trim().min(1).max(100).optional().describe("search: a name, ticker or ISIN"),
123	  isin: z.string().regex(/^[A-Z]{2}[A-Z0-9]{9}\d$/).optional().describe("quote, chart and news"),
124	  timeframe: z.enum(["one_day", "seven_days", "one_month", "three_months", "six_months", "year_to_date", "one_year", "max"]).optional().describe("chart only; default one_month"),
125	}).strict();
126	
127	const quoteSchema = z.object({ midPrice: decimal, currency: code, timestampUtc: z.string().optional(), isOutdated: z.boolean().optional() }).passthrough();
128	const searchSchema = z.object({ results: z.array(z.object({ isin: z.string(), name: z.string(), securityType: z.string().optional(), currentQuote: quoteSchema.nullable().optional() })).default([]) });
129	const chartSchema = z.object({ currency: code, dataPoints: z.array(z.object({ midPrice: decimal, timestampUtc: z.string() })).default([]) });
130	const newsSchema = z.object({ summary: z.object({ short: z.string().optional(), long: z.string().optional() }).nullable().optional() });
131	const quoteResultSchema = z.object({ security: z.object({ isin: z.string(), name: z.string().optional(), securityType: z.string().optional(),
132	  quote: quoteSchema.and(z.object({ performances: z.array(z.object({ timeframe: z.string(), performance: decimal.nullable().optional() })).optional() })) }) });
133	const quoted = (quote: z.infer<typeof quoteSchema> | null | undefined) => quote ? { priceMinor: toMinor(quote.midPrice, quote.currency), currencyCode: quote.currency, at: quote.timestampUtc ?? null, outdated: quote.isOutdated ?? false } : null;
134	
135	/** Any security on Scalable: search by name, its live quote, its price chart (summarised) or its news. */
136	export async function investmentsSecurity(mcp: ScalableMcp, input: z.infer<typeof securityInput>) {
137	  if (input.action === "search") {
138	    if (!input.query) throw new Error("Search needs a query");
139	    const found = searchSchema.parse(await mcp.callTool("search_securities", { query: input.query }));
140	    return { results: found.results.slice(0, 10).map(item => ({ isin: item.isin, name: item.name, type: item.securityType ?? null, quote: quoted(item.currentQuote) })) };
141	  }
142	  if (!input.isin) throw new Error(`${input.action} needs an ISIN; search first`);
143	  if (input.action === "quote") {
144	    const { security } = quoteResultSchema.parse(await mcp.callTool("get_security_quote", { isin: input.isin }));
145	    return { isin: security.isin, name: security.name ?? null, type: security.securityType ?? null, quote: quoted(security.quote),
146	      // Scalable's own moves for the security, as percentages.
147	      moves: (security.quote.performances ?? []).flatMap(entry => PERIODS[entry.timeframe] && entry.performance != null ? [{ period: PERIODS[entry.timeframe], percent: Math.round(Number(entry.performance) * 10000) / 100 }] : []) };
148	  }
149	  if (input.action === "chart") {
150	    const timeframe = input.timeframe ?? "one_month";
151	    const chart = chartSchema.parse(await mcp.callTool("get_security_chart", { isin: input.isin, timeframe }));
152	    const prices = chart.dataPoints.map(point => Number(point.midPrice));
153	    if (!prices.length) return { isin: input.isin, timeframe, points: [] };
154	    const first = prices[0], last = prices.at(-1)!;
155	    // About 24 evenly spaced points are enough to describe or draw the trend.
156	    const step = Math.max(1, Math.ceil(chart.dataPoints.length / 24));
157	    return { isin: input.isin, timeframe, currencyCode: chart.currency, firstMinor: toMinor(first, chart.currency), lastMinor: toMinor(last, chart.currency),
158	      lowMinor: toMinor(Math.min(...prices), chart.currency), highMinor: toMinor(Math.max(...prices), chart.currency), changePercent: Math.round((last - first) / first * 10000) / 100,
159	      points: chart.dataPoints.filter((_, index) => index % step === 0 || index === chart.dataPoints.length - 1).map(point => ({ at: point.timestampUtc, priceMinor: toMinor(point.midPrice, chart.currency) })) };
160	  }
161	  const news = newsSchema.parse(await mcp.callTool("get_security_news", { isin: input.isin, locale: "en_US" }));
162	  // Third-party text: the system prompt tells the model never to follow instructions in tool results.
163	  return { isin: input.isin, summary: news.summary?.short ?? null, detail: news.summary?.long?.slice(0, 2500) ?? null };
164	}
165	
166	const dayMove = (quote: unknown) => {
167	  const today = (quote as { performances?: { timeframe?: string; performance?: number | string | null }[] } | null)?.performances?.find(entry => entry.timeframe === "INTRADAY")?.performance;
168	  return today == null ? null : Math.round(Number(today) * 10000) / 100;
169	};
170	const watchlistSchema = z.object({ items: z.array(z.object({ isin: z.string(), name: z.string(), securityType: z.string().optional(), currentQuote: quoteSchema.nullable().optional() })).default([]) });
171	export async function investmentsWatchlist(mcp: ScalableMcp) {
172	  return { items: watchlistSchema.parse(await mcp.callTool("list_watchlist_items")).items.map(item => ({ isin: item.isin, name: item.name, type: item.securityType ?? null, quote: quoted(item.currentQuote),
173	    dayPercent: dayMove(item.currentQuote) })) };
174	}
