1	import { createHash, randomBytes } from "node:crypto";
2	import { z } from "zod";
3	
4	// Scalable Capital's official MCP server. OAuth 2.1 with dynamic client registration and PKCE
5	// (public client, no secret); the bearer token then calls MCP tools over Streamable HTTP.
6	// Hosted redirect URIs must be on Scalable's SaaS allowlist; localhost registers freely.
7	// SCALABLE_MCP_ORIGIN points browser tests at a local stand-in (e2e/mocks/scalable-mcp.mjs); unset in real use.
8	const ISSUER = process.env.SCALABLE_MCP_ORIGIN || "https://mcp.scalable.capital";
9	export const SCALABLE_MCP_URL = `${ISSUER}/mcp`;
10	const SCOPE = "openid profile offline_access";
11	const PROTOCOL_VERSION = "2025-06-18";
12	
13	export class ScalableError extends Error {
14	  /** `refused` marks an answer from the tool itself: Scalable decided, so nothing was left half-done. */
15	  constructor(message: string, readonly status: number, readonly expired = false, readonly refused = false) { super(message); }
16	}
17	
18	const base64url = (bytes: Buffer) => bytes.toString("base64url");
19	
20	export function pkcePair() {
21	  const verifier = base64url(randomBytes(32));
22	  return { verifier, challenge: base64url(createHash("sha256").update(verifier).digest()) };
23	}
24	
25	async function json<T>(response: Response, schema: z.ZodType<T>): Promise<T> {
26	  const body = await response.json().catch(() => null);
27	  if (!response.ok) {
28	    const code = z.object({ error: z.string() }).safeParse(body).data?.error;
29	    throw new ScalableError(`Scalable returned ${response.status}${code ? ` (${code})` : ""}`, response.status, code === "invalid_grant" || response.status === 401);
30	  }
31	  return schema.parse(body);
32	}
33	
34	export async function registerClient(redirectUri: string, fetcher: typeof fetch = fetch) {
35	  const response = await fetcher(`${ISSUER}/register`, {
36	    method: "POST", headers: { "content-type": "application/json" },
37	    body: JSON.stringify({ client_name: "Moneo", redirect_uris: [redirectUri], grant_types: ["authorization_code", "refresh_token"],
38	      response_types: ["code"], token_endpoint_auth_method: "none", scope: SCOPE }),
39	  });
40	  return (await json(response, z.object({ client_id: z.string().min(1).max(200) }))).client_id;
41	}
42	
43	export function authorizeUrl(input: { clientId: string; redirectUri: string; state: string; challenge: string }) {
44	  const url = new URL(`${ISSUER}/authorize`);
45	  url.search = new URLSearchParams({ response_type: "code", client_id: input.clientId, redirect_uri: input.redirectUri, scope: SCOPE,
46	    state: input.state, code_challenge: input.challenge, code_challenge_method: "S256", resource: SCALABLE_MCP_URL }).toString();
