53	async function token(params: Record<string, string>, fetcher: typeof fetch, previousRefresh: string | null = null): Promise<ScalableTokens> {
54	  const response = await fetcher(`${ISSUER}/token`, {
55	    method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" },
56	    body: new URLSearchParams({ ...params, resource: SCALABLE_MCP_URL }).toString(),
57	  });
58	  const body = await json(response, tokenSchema);
59	  // Without expires_in, assume a short life so the next call refreshes instead of failing.
60	  return { accessToken: body.access_token, refreshToken: body.refresh_token ?? previousRefresh, expiresAt: Date.now() + (body.expires_in ?? 300) * 1000 };
61	}
