63	export const exchangeCode = (input: { clientId: string; redirectUri: string; code: string; verifier: string }, fetcher: typeof fetch = fetch) =>
64	  token({ grant_type: "authorization_code", client_id: input.clientId, redirect_uri: input.redirectUri, code: input.code, code_verifier: input.verifier }, fetcher);
