69	const rpcSchema = z.object({ id: z.union([z.number(), z.string()]).optional(), result: z.unknown().optional(), error: z.object({ message: z.string() }).optional() });
70	
71	/** The JSON-RPC answer to `id`, from a plain JSON body or a Server-Sent Events stream. */
72	export function rpcMessage(text: string, contentType: string, id: number) {
73	  const messages = contentType.includes("text/event-stream")
74	    ? text.split(/\r?\n/).filter(line => line.startsWith("data:")).map(line => line.slice(5).trim()).filter(Boolean).map(data => JSON.parse(data) as unknown)
75	    : [JSON.parse(text) as unknown];
76	  const message = messages.map(item => rpcSchema.safeParse(item).data).find(item => item?.id === id);
77	  if (!message) throw new ScalableError("Scalable MCP sent no answer", 502);
78	  if (message.error) throw new ScalableError(`Scalable MCP: ${message.error.message}`, 502);
79	  return message.result;
80	}
81	
82	const toolResultSchema = z.object({
83	  content: z.array(z.object({ type: z.string(), text: z.string().optional() })).default([]),
84	  structuredContent: z.unknown().optional(), isError: z.boolean().optional(),
85	});
86	
87	/** Read-only MCP session. Tool results are structured content, or the text content parsed as JSON when possible. */
88	export function scalableMcp(accessToken: string, fetcher: typeof fetch = fetch) {
89	  let sessionId: string | null = null, protocol = PROTOCOL_VERSION, nextId = 0;
90	  async function rpc(method: string, params?: unknown, notification = false) {
91	    const id = ++nextId;
92	    const response = await fetcher(SCALABLE_MCP_URL, {
93	      method: "POST",
94	      headers: { authorization: `Bearer ${accessToken}`, "content-type": "application/json", accept: "application/json, text/event-stream",
95	        "mcp-protocol-version": protocol, ...(sessionId ? { "mcp-session-id": sessionId } : {}) },
96	      body: JSON.stringify(notification ? { jsonrpc: "2.0", method, params } : { jsonrpc: "2.0", id, method, params }),
97	    });
98	    if (!response.ok) throw new ScalableError(`Scalable MCP returned ${response.status}`, response.status, response.status === 401);
99	    sessionId = response.headers.get("mcp-session-id") ?? sessionId;
100	    if (notification) return undefined;
101	    return rpcMessage(await response.text(), response.headers.get("content-type") ?? "", id);
102	  }
103	  return {
104	    async connect() {
105	      const result = z.object({ protocolVersion: z.string() }).parse(await rpc("initialize", { protocolVersion: PROTOCOL_VERSION, capabilities: {}, clientInfo: { name: "Moneo", version: "1.0.0" } }));
106	      protocol = result.protocolVersion;
107	      await rpc("notifications/initialized", undefined, true);
108	    },
109	    listTools: async () => z.object({ tools: z.array(z.object({ name: z.string() }).passthrough()) }).parse(await rpc("tools/list", {})).tools,
110	    async callTool(name: string, args: Record<string, unknown> = {}): Promise<unknown> {
111	      const result = toolResultSchema.parse(await rpc("tools/call", { name, arguments: args }));
112	      const text = result.content.filter(item => item.type === "text").map(item => item.text ?? "").join("\n");
113	      if (result.isError) throw new ScalableError(`Scalable tool ${name} failed: ${text.slice(0, 300)}`, 502, false, true);
114	      if (result.structuredContent !== undefined) return result.structuredContent;
115	      try { return JSON.parse(text) as unknown; } catch { return text; }
116	    },
117	  };
118	}
119	export type ScalableMcp = ReturnType<typeof scalableMcp>;
