24	/** Shortest exact decimal text for a JSON number (never exponent notation). */
25	export function decimalText(value: number) {
26	  const text = String(Math.abs(value));
27	  return text.includes("e") ? Math.abs(value).toFixed(18).replace(/\.?0+$/, "") : text;
28	}
29	const minor = (value: number, currency: string) => BigInt(Math.round(value * 10 ** minorDigits(currency)));
