26	// Recorded net worth on each date: the latest recorded account balance plus the posted transactions after
27	// its day, and the latest standalone valuation dated on or before it. No FX and no interpolation.
28	// With a ledger, a date before an account's first recorded balance is worked back from that balance by
29	// removing the posted transactions after the date, but only from the day before its first posting, since
30	// earlier activity is not on record. `known` is false when nothing covers the date.
31	// Today's point should come from `currentNetWorth`, which uses the exact resolved balances every screen shows.
32	// ponytail: archived accounts are left out (matching Home); include them if history must show closed accounts.
33	export function netWorthSeries({ dates, timeZone, accountIds, snapshots, valuations, removedOn, ledger = [] }: {
34	  dates: string[]; timeZone: string; accountIds: Set<string>; snapshots: Snapshot[]; valuations: Valuation[]; removedOn: Map<string, string>; ledger?: Posting[];
35	}): NetWorthPoint[] {
36	  const balances = snapshots.filter(row => !row.undone_at && accountIds.has(row.account_id))
37	    .map(row => ({ key: row.account_id, date: calendarDate(row.as_of, timeZone), at: row.as_of, amount: BigInt(row.amount_minor), currency: row.currency_code,
38	      // As in resolveBalances: a balance typed in during the day is moved by later timed postings that day; a dated one is that day's closing balance.
39	      observed: calendarDate(new Date(Date.parse(row.as_of) - 1).toISOString(), timeZone) === calendarDate(row.as_of, timeZone) }));
40	  const values = valuations.filter(row => !row.linked_account_id)
41	    .map(row => ({ key: row.item_id, date: row.as_of, at: row.created_at, amount: BigInt(row.amount_minor), currency: row.currency_code, debt: row.kind === "debt" }));
42	  const latest = <T extends { key: string; date: string; at: string }>(rows: T[], date: string) => {
43	    const pick = new Map<string, T>();
44	    for (const row of rows) {
45	      if (row.date > date) continue;
46	      const prior = pick.get(row.key);
47	      if (!prior || row.date > prior.date || (row.date === prior.date && row.at >= prior.at)) pick.set(row.key, row);
48	    }
49	    return pick.values();
50	  };
51	  const posted = ledger.filter(row => row.status === "posted" && accountIds.has(row.account_id))
52	    .map(row => ({ ...row, day: row.posted_at ? calendarDate(row.posted_at, timeZone) : row.posted_on, amount: BigInt(row.amount_minor) }));
53	  const afterBalance = (row: typeof posted[number], balance: typeof balances[number]) => row.day > balance.date ||
54	    (row.day === balance.date && balance.observed && !!row.posted_at && Date.parse(row.posted_at) > Date.parse(balance.at));
55	  const sum = (rows: typeof posted) => rows.reduce((total, row) => total + row.amount, 0n);
56	  const firstPosted = new Map<string, string>();
57	  for (const row of posted) if (!firstPosted.has(row.account_id) || row.posted_on < firstPosted.get(row.account_id)!) firstPosted.set(row.account_id, row.posted_on);
58	  const dayBefore = (date: string) => new Date(Date.parse(`${date}T00:00:00Z`) - 86400000).toISOString().slice(0, 10);
59	  return dates.map(date => {
60	    const point: NetWorthPoint = { date, accounts: new Map(), assets: new Map(), debts: new Map(), known: false };
61	    const recorded = [...latest(balances, date)];
62	    for (const row of recorded) add(point.accounts, row.currency, row.amount + sum(posted.filter(item => item.account_id === row.key && item.currency_code === row.currency && afterBalance(item, row) && item.day <= date)));
63	    for (const key of accountIds) {
64	      const first = firstPosted.get(key);
65	      if (recorded.some(row => row.key === key) || !first || date < dayBefore(first)) continue;
66	      const next = balances.filter(row => row.key === key && row.date > date).sort((a, b) => a.date.localeCompare(b.date) || a.at.localeCompare(b.at))[0];
67	      if (!next) continue;
68	      add(point.accounts, next.currency, next.amount - sum(posted.filter(row => row.account_id === key && row.currency_code === next.currency && row.day > date && !afterBalance(row, next))));
69	    }
70	    for (const row of latest(values, date)) {
71	      const removed = removedOn.get(row.key);
72	      if (removed && removed <= date) continue;
73	      add(row.debt ? point.debts : point.assets, row.currency, row.amount);
74	    }
75	    point.known = point.accounts.size + point.assets.size + point.debts.size > 0;
76	    return point;
77	  });
78	}
