82	export function currentNetWorth(date: string, accounts: { currency_code: string; balance: { amount_minor: string | null } }[],
83	  valuations: { amountMinor: bigint; currencyCode: string; debt: boolean }[]): NetWorthPoint {
84	  const point: NetWorthPoint = { date, accounts: new Map(), assets: new Map(), debts: new Map(), known: false };
85	  for (const account of accounts) if (account.balance.amount_minor !== null) add(point.accounts, account.currency_code, BigInt(account.balance.amount_minor));
86	  for (const valuation of valuations) add(valuation.debt ? point.debts : point.assets, valuation.currencyCode, valuation.amountMinor);
87	  point.known = point.accounts.size + point.assets.size + point.debts.size > 0;
88	  return point;
89	}
