9	// Daily valuation: each hourly run syncs what isn't dated today yet in the workspace's timezone, so a
10	// new day needs no waiting and a failed sync retries next hour. Older values still count, flagged.
11	export async function GET(request: Request) {
12	  const secret = process.env.CRON_SECRET;
13	  if (!secret || request.headers.get("authorization") !== `Bearer ${secret}`) return Response.json({ error: "Unauthorized" }, { status: 401 });
14	  if (!process.env.NEXT_PUBLIC_SUPABASE_URL || !scalableConfigured()) return Response.json({ error: "Scalable sync unavailable" }, { status: 503 });
15	  // ponytail: 100 connections per run, sequential; page and fan out before going multi-user.
16	  const db = serviceDb();
17	  const { data, error } = await db.from("scalable_connections").select("id, workspace_id, last_synced_at").eq("status", "active").order("id").limit(100);
18	  if (error) return Response.json({ error: "Scalable connections unavailable" }, { status: 503 });
19	  let synced = 0, failed = 0;
20	  for (const row of data ?? []) {
21	    try {
22	      const { timezone } = await loadWorkspaceSettings(db, row.workspace_id);
23	      if (row.last_synced_at && calendarDate(row.last_synced_at, timezone) === calendarDate(new Date(), timezone)) continue;
24	      await syncScalable(row.id, row.workspace_id); synced++;
25	    } catch { failed++; }
26	  }
27	  return Response.json({ synced, failed });
28	}
