89	export function wealthOverview(items: Pick<WealthItem, "id" | "name" | "kind" | "amount_minor" | "currency_code" | "as_of" | "removed_at">[]) {
90	  const totals = new Map<string, bigint>();
91	  const listed = items.filter(item => !item.removed_at).map(item => {
92	    const iou = parseIouName(item.name);
93	    const group = iou?.direction ?? item.kind;
94	    const key = `${group}:${item.currency_code}`;
95	    totals.set(key, (totals.get(key) ?? 0n) + BigInt(item.amount_minor));
96	    return { id: item.id, group, name: item.name, ...(iou && { person: iou.person }), amountMinor: item.amount_minor,
97	      amountFormatted: formatMoney(item.amount_minor, item.currency_code), currencyCode: item.currency_code, asOf: item.as_of };
98	  });
99	  return {
100	    items: listed,
101	    totals: [...totals].map(([key, minor]) => { const [group, currencyCode] = key.split(":"); return { group, currencyCode, amountMinor: minor.toString(), amountFormatted: formatMoney(minor, currencyCode) }; }),
102	    groups: "lent: money the user lent to a person (an asset); borrowed: money the user owes a person (a debt); asset, holding, debt: other Wealth items.",
103	    link: "/money/wealth",
