107	export async function loadWealthItems(client: SupabaseClient, workspaceId: string, includeRemoved = false): Promise<WealthItem[]> {
108	  const rows: WealthItem[] = [];
109	  for (let offset = 0; ; offset += 500) {
110	    let query = client.from("wealth_items").select("id, name, kind, currency_code, amount_minor::text, quantity_text, unit_price_text, cost_basis_minor::text, as_of, linked_account_id, payment_account_id, annual_rate_text, monthly_payment_minor::text, next_payment_on, payment_assumption_id, payment_transaction_id, version, removed_at")
111	      .eq("workspace_id", workspaceId).order("created_at").order("id");
112	    if (!includeRemoved) query = query.is("removed_at", null);
113	    const result = await query.range(offset, offset + 499);
114	    if (result.error) throw result.error;
115	    rows.push(...result.data as WealthItem[]);
116	    if (!result.data || result.data.length < 500) return rows.map(row => ({ ...row,
117	      sourceCoverage: buildSourceCoverage({ from: row.as_of, to: row.as_of, currencyCode: row.currency_code, recordBasis: "manual_wealth" }, []) }));
