121	export function buildDebtForecast(items: WealthItem[], accounts: { id: string; type?: string; currency_code: string; archived_at?: string | null }[], ledger: { id: string; account_id: string; amount_minor: string | number; currency_code: string; posted_on: string; status: string; pending_released_minor?: string }[], assumptions: { id: string; account_id: string | null; amount_minor: string; currency_code: string; cadence: string; starts_on: string; ends_on: string | null }[], today: string, days: number): { events: { date: string; accountId: string; currencyCode: string; amountMinor: bigint }[]; excludedAssumptionIds: string[]; missingInputs: string[] } {
122	  const minor = (value: string | number) => { if (typeof value === "number" && !Number.isSafeInteger(value)) throw new Error("Unsafe debt ledger money"); return BigInt(value); };
123	  const events: { date: string; accountId: string; currencyCode: string; amountMinor: bigint }[] = [];
124	  const excludedAssumptionIds: string[] = []; const missingInputs: string[] = []; const provenance = new Set<string>();
125	  for (const item of items.filter(item => item.kind === "debt" && !item.removed_at)) {
126	    const missing = (reason: string) => missingInputs.push(`debt:${item.id}:${reason}`);
127	    if (BigInt(item.amount_minor) === 0n) continue;
128	    if (item.as_of !== today) { missing("principal valuation is historical"); continue; }
129	    const account = accounts.find(account => account.id === item.payment_account_id);
130	    if (!account || account.archived_at || !["checking", "savings", "cash", "wallet"].includes(account.type ?? "") || account.currency_code !== item.currency_code) { missing("liquid repayment account"); continue; }
131	    if (!item.next_payment_on || !item.annual_rate_text || BigInt(item.monthly_payment_minor ?? "0") <= 0n) { missing("repayment assumptions"); continue; }
132	    const keys = [item.payment_assumption_id ? `assumption:${item.payment_assumption_id}` : null, item.payment_transaction_id ? `pending:${item.payment_transaction_id}` : null].filter((key): key is string => key !== null);
133	    if (keys.some(key => provenance.has(key))) { missing("duplicate repayment provenance"); continue; }
134	    keys.forEach(key => provenance.add(key));
135	    if (item.payment_assumption_id) {
136	      const assumption = assumptions.find(assumption => assumption.id === item.payment_assumption_id);
137	      if (!assumption || assumption.account_id !== account.id || assumption.currency_code !== item.currency_code || assumption.amount_minor !== `-${item.monthly_payment_minor}` || assumption.cadence !== "monthly" || assumption.starts_on !== item.next_payment_on || assumption.ends_on !== null) {
138	        missing("repayment association changed"); continue;
139	      }
140	    }
141	    let payments: ReturnType<typeof debtPayments>;
142	    try { payments = debtPayments({ principalMinor: BigInt(item.amount_minor), annualRate: item.annual_rate_text, monthlyPaymentMinor: BigInt(item.monthly_payment_minor!), nextPaymentOn: item.next_payment_on }, today, days); }
143	    catch { missing("repayment assumptions need update"); continue; }
144	    const pending = item.payment_transaction_id ? ledger.find(row => row.id === item.payment_transaction_id) : undefined;
145	    if (item.payment_transaction_id && (!pending || BigInt(pending.pending_released_minor ?? "0") > 0n || pending.account_id !== account.id || pending.currency_code !== item.currency_code || pending.status !== "pending" || pending.posted_on !== item.next_payment_on || minor(pending.amount_minor) !== -BigInt(item.monthly_payment_minor!))) {
146	      missing("pending repayment association changed"); continue;
147	    }
148	    if (pending && payments[0] && minor(pending.amount_minor) !== -payments[0].paymentMinor) { missing("pending repayment differs from final payoff"); continue; }
149	    const itemEvents: typeof events = [];
150	    const missingBeforePayments = missingInputs.length;
151	    for (const payment of payments) {
152	      // Current booked balances already deduct these dated pending holds in evaluatePlan.
153	      const matchingHolds = payment.date <= today ? ledger.filter(row => row.account_id === account.id && row.currency_code === item.currency_code && row.status === "pending" && BigInt(row.pending_released_minor ?? "0") < -minor(row.amount_minor) && row.posted_on === payment.date && minor(row.amount_minor) === -payment.paymentMinor) : [];
154	      if (matchingHolds.length) {
155	        if (matchingHolds.length !== 1 || matchingHolds[0].id !== item.payment_transaction_id || BigInt(matchingHolds[0].pending_released_minor ?? "0") > 0n) missing("pending repayment needs association");
156	        continue;
157	      }
158	      itemEvents.push({ date: payment.date, accountId: account.id, currencyCode: item.currency_code, amountMinor: -payment.paymentMinor });
159	    }
160	    // Retain an existing confirmed obligation when its proposed replacement is invalid.
161	    if (missingInputs.length === missingBeforePayments) {
162	      if (item.payment_assumption_id) excludedAssumptionIds.push(item.payment_assumption_id);
163	      events.push(...itemEvents);
164	    }
165	  }
166	  return { events, excludedAssumptionIds, missingInputs };
167	}
