1	export function calendarDate(value: string | Date = new Date(), timeZone = "Europe/Berlin"): string {
2	  const parts = new Intl.DateTimeFormat("en-CA", { timeZone, year: "numeric", month: "2-digit", day: "2-digit" })
3	    .formatToParts(new Date(value));
4	  const part = (type: string) => parts.find(item => item.type === type)!.value;
5	  return `${part("year")}-${part("month")}-${part("day")}`;
6	}
7	
8	export function reviewedLocalTimestamp(value: string, timeZone: string): string {
9	  const match = /^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{2}):(\d{2}):(\d{2})(?:\.(\d{1,3}))?$/.exec(value.trim());
10	  if (!match) throw new Error("Invalid local timestamp");
11	  const wall = Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]), Number(match[4]), Number(match[5]), Number(match[6]));
12	  const checked = new Date(wall);
13	  if (checked.getUTCFullYear() !== Number(match[1]) || checked.getUTCMonth() + 1 !== Number(match[2]) || checked.getUTCDate() !== Number(match[3]) ||
14	      Number(match[4]) > 23 || Number(match[5]) > 59 || Number(match[6]) > 59) throw new Error("Invalid local timestamp");
15	  const formatter = new Intl.DateTimeFormat("en-CA", { timeZone, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit" });
16	  const localWall = (instant: number) => {
17	    const parts = formatter.formatToParts(new Date(instant));
18	    const part = (key: string) => Number(parts.find(item => item.type === key)!.value);
19	    return Date.UTC(part("year"), part("month") - 1, part("day"), part("hour"), part("minute"), part("second"));
20	  };
21	  const candidates = new Set<number>();
22	  for (const probe of [wall - 86400000, wall, wall + 86400000]) {
23	    const candidate = wall - (localWall(probe) - probe);
24	    if (localWall(candidate) === wall) candidates.add(candidate);
25	  }
26	  if (candidates.size !== 1) throw new Error("Source timestamp is ambiguous or nonexistent in the reviewed timezone");
27	  return new Date([...candidates][0] + Number((match[7] ?? "").padEnd(3, "0"))).toISOString();
28	}
29	
30	export function calendarDayBoundary(date: string, timeZone = "Europe/Berlin"): string {
31	  return reviewedLocalTimestamp(`${date}T00:00:00`, timeZone);
32	}
