6	// Disconnect: forget the tokens. Synced data stays. Scalable access itself is ended under
7	// Profile → Security → Agentic Investing in Scalable.
8	export async function DELETE(_request: Request, { params }: { params: Promise<{ id: string }> }) {
9	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
10	  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
11	  const id = z.string().uuid().safeParse((await params).id);
12	  if (!id.success) return NextResponse.json({ error: "Not found" }, { status: 404 });
13	  const revoked = await serviceDb().from("scalable_connections").update({ status: "revoked", tokens_encrypted: null, pkce_verifier_encrypted: null })
14	    .eq("id", id.data).eq("workspace_id", context.workspace.id).select("id");
15	  if (revoked.error) return NextResponse.json({ error: "Scalable could not be disconnected. Try again." }, { status: 500 });
16	  if (!revoked.data.length) return NextResponse.json({ error: "Not found" }, { status: 404 });
17	  return NextResponse.json({ status: "revoked" });
18	}
