    const held = heldCoins.get(ticker) ?? 0n, replayed = coins.get(ticker)?.coins ?? 0n;
    if (absolute(replayed - held) > TOLERANCE) return fail(`${ticker} coins replay to ${decimalOf(replayed)}, but Scalable holds ${decimalOf(held)}`);
  }
